import{_ as e,o as a,a as r,b as s}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"比较与选择","link":"/api/SIMD-API/basic_api/memory_vector_compute/compare_and_select/compare_and_select"},{"text":"概述","link":"/api/SIMD-API/basic_api/memory_vector_compute/compare_and_select/overview"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/compare_and_select/overview.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/compare_and_select/overview.md","lastUpdated":1785832713000}'),d={name:"api/SIMD-API/basic_api/memory_vector_compute/compare_and_select/overview.md"};function o(m,t,c,p,_,i){return a(),r("div",null,[...t[0]||(t[0]=[s('<div><article class="markdown-body"><h1>概述</h1><p>Compare、Compares称之为比较接口，用于逐元素比较Tensor或Scalar的大小，并根据比较结果生成掩码。Select、GatherMask称之为选择接口，用于根据掩码条件从源操作数中选取元素输出到目的操作数。推荐使用场景如下：</p><p><strong>表1</strong> 比较与选择接口推荐使用场景</p><table><thead><tr><th>API</th><th>核心功能</th><th>Mask类型</th><th>应用场景</th></tr></thead><tbody><tr><td><a href="Compare.html">Compare</a></td><td>逐元素比较两个tensor大小，如果比较后的结果为真，则输出结果的对应比特位为1，否则为0。支持多种比较模式（等于、小于、大于...）。<br>不支持Vector计算的Mask设置。结果存入UB。</td><td>未使用</td><td>逐元素比较，结果写入内存。</td></tr><tr><td><a href="Compare_store_to_register.html">Compare（结果存入寄存器）</a></td><td>逐元素比较两个tensor大小，如果比较后的结果为真，则输出结果的对应比特位为1，否则为0。支持多种比较模式。<br>支持Vector计算的Mask设置。结果暂存CmpMask寄存器。详情参考<a href="#cmpMask-vectorMask">表2 CmpMask与VectorMask</a>。</td><td>src传参mask用于Vector计算；<br>输出结果为CmpMask（比较掩码）。</td><td>逐元素比较，结果写寄存器。</td></tr><tr><td><a href="Compares.html">Compares</a></td><td>逐元素比较一个tensor中的元素和另一个scalar的大小，如果比较后的结果为真，则输出结果的对应比特位为1，否则为0。<br>支持多种比较模式。</td><td>未使用</td><td>张量和标量逐元素比较，结果写入内存。</td></tr><tr><td><a href="Select.html">Select</a></td><td>给定两个源操作数src0和src1，根据selMask（用于选择的Mask掩码）的比特位值选取元素。<br>支持CmpMask设置，支持用于Vector计算的Mask的设置。详情参考<a href="#cmpMask-vectorMask">表2 CmpMask与VectorMask</a>。</td><td>src传参mask用于Vector计算；<br>src传参selMask为CmpMask（比较掩码）。</td><td>掩码条件选择输出。</td></tr><tr><td><a href="GetCmpMask_ISASI.html">GetCmpMask(ISASI)</a></td><td>此接口用于获取<a href="Compare_store_to_register.html">Compare（结果存入寄存器）</a>指令的比较结果。</td><td>CmpMask（比较掩码）</td><td>读取寄存器比较掩码。</td></tr><tr><td><a href="SetCmpMask_ISASI.html">SetCmpMask(ISASI)</a></td><td>为<a href="Select.html">Select</a>不传入mask参数的接口设置比较寄存器。</td><td>CmpMask（比较掩码）</td><td>设置寄存器比较掩码。</td></tr><tr><td><a href="GatherMask.html">GatherMask</a></td><td>基于掩码（用于Vector计算）从输入张量中提取有效元素。</td><td>src1传参GatherMask（数据收集掩码）。</td><td>按掩码提取有效元素。</td></tr></tbody></table><p><strong>表2</strong> CmpMask与VectorMask<a id="cmpMask-vectorMask"></a></p><table><thead><tr><th>名称</th><th>描述</th><th>数据来源</th><th>作用范围</th></tr></thead><tbody><tr><td>CmpMask</td><td>Compare比较指令的“结果寄存器”。</td><td>•由<a href="Compare_store_to_register.html">Compare（结果存入寄存器）</a>接口的结果写入。<br>• Select接口selMask参数传入。<br>•通过SetCmpMask接口设置。</td><td>用于记录元素比较的布尔结果，主要为后续Select指令使用。</td></tr><tr><td>VectorMask</td><td>控制数据元素是否参与计算的标识位序列的Mask寄存器。详情参考<a href="../SIMD_compute/mask.html">掩码</a>。</td><td>• <a href="../SIMD_compute/mask.html#%E6%8E%A5%E5%8F%A3%E5%86%85%E8%AE%BE%E7%BD%AEmask">接口内设置mask</a><br>• <a href="../SIMD_compute/mask.html#%E6%8E%A5%E5%8F%A3%E5%A4%96%E8%AE%BE%E7%BD%AEmask">接口外设置mask</a></td><td>用于逐元素控制向量计算，决定哪些数据元素参与计算。</td></tr></tbody></table></article></div>',1)])])}const l=e(d,[["render",o]]);export{h as __pageData,l as default};
